#include "EventNotificationRegistry.h"
EventNotificationRegistry::EventNotificationRegistry():entries_{},size_(0U),locked_(false){}
RuntimeIntegrationResult EventNotificationRegistry::registerMapping(const EventNotificationMapping& m){if(locked_)return RuntimeIntegrationResult::REGISTRY_LOCKED;if(!m.isValid())return RuntimeIntegrationResult::INVALID_INPUT;if(find(m.eventType())!=nullptr)return RuntimeIntegrationResult::DUPLICATE_MAPPING;if(size_>=EVENT_NOTIFICATION_MAX_MAPPINGS)return RuntimeIntegrationResult::REGISTRY_FULL;EventNotificationRegistryEntry& e=entries_[size_];for(size_t i=0U;i<m.targetLength();++i)e.target[i]=m.target()[i];e.mapping=EventNotificationMapping::create(m.eventType(),m.minimumSeverity(),m.channelId(),m.priority(),m.ttlMs(),e.target,m.targetLength(),m.enabled());if(!e.mapping.isValid())return RuntimeIntegrationResult::INTERNAL_ERROR;++size_;return RuntimeIntegrationResult::SUCCESS;}
const EventNotificationMapping* EventNotificationRegistry::find(EventType type)const{for(size_t i=0U;i<size_;++i)if(entries_[i].mapping.eventType()==type)return &entries_[i].mapping;return nullptr;}const EventNotificationMapping* EventNotificationRegistry::at(size_t i)const{return i<size_?&entries_[i].mapping:nullptr;}size_t EventNotificationRegistry::size()const{return size_;}size_t EventNotificationRegistry::capacity()const{return EVENT_NOTIFICATION_MAX_MAPPINGS;}bool EventNotificationRegistry::isLocked()const{return locked_;}RuntimeIntegrationResult EventNotificationRegistry::lock(){locked_=true;return RuntimeIntegrationResult::SUCCESS;}
